        const cancel = labelSource.standardButton(Dialog.Cancel)
        if (save)
            saveLabel = save.text
        if (cancel)
            cancelLabel = cancel.text
    }

    background: KosSurface {
        radius: AppTheme.smallRadius + 4
        fillColor: AppTheme.dark ? "#262626" : "#F7F7F7"
        elevation: 0.5
